Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.Scanner;

public class Second {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String st = scanner.next();
        char[] c = st.toCharArray();
        int maxLength = 0, countBrackets = 0;
        StringBuilder sb = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();

        for (int i = 0; i < n; i++) {
            if (c[i] == '(') {
                sb.append("_");
                i++;
                while (i < n && c[i] != ')') {
                    sb2.append(c[i]);
                    i++;
                }
                sb2.append("_");
            } else if (i < n) {
                sb.append(c[i]);
            }
        }

        String[] parts = sb.toString().split("_");
        for (String part : parts) {
            maxLength = Math.max(maxLength, part.length());
        }

        String[] bracketParts = sb2.toString().split("_");
        for (String part : bracketParts) {
            if (part.length() > 0) {
                countBrackets++;
            }
        }

        System.out.println(maxLength + " " + countBrackets);
        scanner.close();
    }
}
